var i=`domain-driven-design-ddd`;var n=20;var o={en:[{id:`T020-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Domain-Driven Design (DDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Event-Driven Architecture communicates facts about state changes through events.`},{id:`B`,text:`Hexagonal Architecture isolates the application core behind explicit ports.`},{id:`C`,text:`Domain-Driven Design aligns software structure with business meaning through shared language, bounded contexts, entities, value objects, aggregates, and domain models.`},{id:`D`,text:`CQRS separates write-side commands that enforce business rules from read-side queries optimized for retrieving information.`}]},{id:`T020-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Domain-Driven Design (DDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Each service owns its data and API, deploys on its own cadence, and tolerates remote failures.`},{id:`B`,text:`Maintain clear write invariants while shaping read models for actual query needs.`},{id:`C`,text:`Explore domain workflows with experts, identify where a term changes meaning, and define ownership boundaries.`},{id:`D`,text:`Give each module explicit public APIs, ownership of data and business rules, and import restrictions.`}]},{id:`T020-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`In hospitality, 'guest' can mean a booking contact in reservations and a person with loyalty status in CRM.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Treat those as different context models rather than a single massive Guest entity.`},{id:`B`,text:`Consistent error mapping prevents database exceptions from leaking into user-visible responses.`},{id:`C`,text:`Express controllers translate HTTP input, while MongoDB adapters implement storage details.`},{id:`D`,text:`A read replica is optional.`}]},{id:`T020-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Domain-Driven Design (DDD)`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Not every IO call deserves its own port.`},{id:`B`,text:`Separate read databases add synchronization lag, deployment work and reconciliation paths.`},{id:`C`,text:`Do not split solely by database tables or developer teams.`},{id:`D`,text:`DDD is not a mandate to create repositories and aggregates for every table.`}]},{id:`T020-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Strategic DDD is as important as tactical patterns.`}]}]},{id:`T020-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`DDD means creating an entity class for every database table.`}]}]},{id:`T020-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Domain modeling requires access to knowledgeable stakeholders, and poor context boundaries can multiply translation work.`}]}]},{id:`T020-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Domain-Driven Design (DDD)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Explore domain workflows with experts, identify where a term changes meaning, and define ownership boundaries.`},{id:`B`,text:`Publishing an event guarantees it will be processed immediately and exactly once.`},{id:`C`,text:`Domain-Driven Design aligns software structure with business meaning through shared language, bounded contexts, entities, value objects, aggregates, and domain models.`},{id:`D`,text:`Bounded contexts should always share one unrestricted domain model.`}]},{id:`T020-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Domain-Driven Design (DDD)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Treat those as different context models rather than a single massive Guest entity.`},{id:`B`,text:`A modular monolith cannot enforce useful boundaries without separate network processes.`},{id:`C`,text:`DDD means creating an entity class for every database table.`},{id:`D`,text:`Domain modeling requires access to knowledgeable stakeholders, and poor context boundaries can multiply translation work.`}]},{id:`T020-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`In hospitality, 'guest' can mean a booking contact in reservations and a person with loyalty status in CRM.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to propose monolith and microservice designs for an order platform. Require deployment diagrams, data ownership, failure cases, operational costs, and a migration trigger.`},{id:`B`,text:`Ask an agent to separate booking commands from reporting queries inside a modular monolith first. Define authorization on both paths and note when a separate projection would pay off.`},{id:`C`,text:`Design inventory adjustment with two incoming adapters and one repository port. Have an agent implement tests against both a fake and a real database integration boundary.`},{id:`D`,text:`Have an agent produce a context map for hotel reservations, CRM, and payments using a supplied glossary. Challenge ambiguous terms and derive two aggregate invariants before implementation.`}]},{id:`T020-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`When should identical-looking domain objects live in different bounded contexts?`}]}]},{id:`T020-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`In hospitality, 'guest' can mean a booking contact in reservations and a person with loyalty status in CRM.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Domain-Driven Design (DDD)`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T020-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`In hospitality, 'guest' can mean a booking contact in reservations and a person with loyalty status in CRM.`,b:!0},{t:` — propose three checks for `},{t:`Domain-Driven Design (DDD)`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T020-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`In hospitality, 'guest' can mean a booking contact in reservations and a person with loyalty status in CRM.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T020-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Domain-Driven Design (DDD)`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`In hospitality, 'guest' can mean a booking contact in reservations and a person with loyalty status in CRM.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T020-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Предметно-орієнтоване проєктування (DDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Подієво-орієнтована архітектура передає факти про зміни стану через події.`},{id:`B`,text:`Гексагональна архітектура ізолює ядро застосунку за явними портами.`},{id:`C`,text:`DDD узгоджує структуру системи з бізнес-смислом через спільну мову, bounded contexts, сутності, об’єкти-значення, агрегати й доменні моделі.`},{id:`D`,text:`CQRS відокремлює команди запису, які застосовують бізнес-правила, від запитів читання, оптимізованих для отримання даних.`}]},{id:`T020-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Предметно-орієнтоване проєктування (DDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Кожен сервіс володіє своїми даними й API та розгортається незалежно, враховуючи мережеві відмови.`},{id:`B`,text:`Зберігайте інваріанти на стороні запису, а моделі читання підлаштовуйте під запити.`},{id:`C`,text:`Досліджуйте сценарії разом із фахівцями, визначайте, де термін має інший зміст, і проводьте межі власності.`},{id:`D`,text:`Кожен модуль повинен мати явне публічне API, власні дані й правила та обмежені імпорти.`}]},{id:`T020-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`У готельній сфері «гість» може означати контакт бронювання або учасника програми лояльності в CRM.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Це різні контекстні моделі, а не обов’язково одна величезна сутність Guest.`},{id:`B`,text:`Узгоджений мапінг помилок не дозволяє виняткам БД потрапляти у відповіді користувачу.`},{id:`C`,text:`Express-контролери перетворюють HTTP-вхід, а MongoDB-адаптери відповідають за збереження.`},{id:`D`,text:`Репліка для читання — необов’язкова.`}]},{id:`T020-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Предметно-орієнтоване проєктування (DDD)`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Не кожен виклик IO потребує окремого порту.`},{id:`B`,text:`Окрема БД читання додає затримку синхронізації, роботу з розгортанням і звіркою.`},{id:`C`,text:`Не діліть систему лише за таблицями БД чи командами.`},{id:`D`,text:`DDD не вимагає репозиторію та агрегату для кожної таблиці.`}]},{id:`T020-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Стратегічна частина не менш важлива за тактичні патерни.`}]}]},{id:`T020-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`DDD означає створення класу сутності для кожної таблиці БД.`}]}]},{id:`T020-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Моделювання потребує доступу до експертів предметної області, а невдалі межі контекстів створюють зайві перетворення.`}]}]},{id:`T020-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Предметно-орієнтоване проєктування (DDD)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Досліджуйте сценарії разом із фахівцями, визначайте, де термін має інший зміст, і проводьте межі власності.`},{id:`B`,text:`Публікація події гарантує її миттєву обробку рівно один раз.`},{id:`C`,text:`DDD узгоджує структуру системи з бізнес-смислом через спільну мову, bounded contexts, сутності, об’єкти-значення, агрегати й доменні моделі.`},{id:`D`,text:`Bounded Contexts завжди мають використовувати одну необмежену доменну модель.`}]},{id:`T020-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Предметно-орієнтоване проєктування (DDD)`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Це різні контекстні моделі, а не обов’язково одна величезна сутність Guest.`},{id:`B`,text:`Модульний моноліт не може мати чітких меж без окремих мережевих процесів.`},{id:`C`,text:`DDD означає створення класу сутності для кожної таблиці БД.`},{id:`D`,text:`Моделювання потребує доступу до експертів предметної області, а невдалі межі контекстів створюють зайві перетворення.`}]},{id:`T020-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`У готельній сфері «гість» може означати контакт бронювання або учасника програми лояльності в CRM.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента порівняти моноліт і мікросервіси для замовлень. Вимагайте схеми розгортання, володіння даними, відмови, експлуатаційні витрати й критерії міграції.`},{id:`B`,text:`Попросіть агента відділити команди бронювання від звітних запитів спершу в модульному моноліті. Визначте авторизацію для обох шляхів і умови появи окремої проєкції.`},{id:`C`,text:`Спроєктуйте зміну складського залишку з двома вхідними адаптерами та портом репозиторію. Попросіть агента перевірити роботу як із fake, так і на межі реальної БД.`},{id:`D`,text:`Попросіть агента створити карту контекстів для бронювань, CRM і платежів за глосарієм. Знайдіть двозначні терміни та сформулюйте два інваріанти агрегатів до реалізації.`}]},{id:`T020-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Коли схожі доменні об’єкти мають існувати в різних bounded contexts?`}]}]},{id:`T020-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`У готельній сфері «гість» може означати контакт бронювання або учасника програми лояльності в CRM.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Предметно-орієнтоване проєктування (DDD)`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T020-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`У готельній сфері «гість» може означати контакт бронювання або учасника програми лояльності в CRM.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Предметно-орієнтоване проєктування (DDD)`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T020-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`У готельній сфері «гість» може означати контакт бронювання або учасника програми лояльності в CRM.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T020-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Предметно-орієнтоване проєктування (DDD)`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`У готельній сфері «гість» може означати контакт бронювання або учасника програми лояльності в CRM.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var a={slug:i,topicId:20,questions:o};export{a as default,o as questions,i as slug,n as topicId};